pub fn fromUTF8(self: SliceWithUnderlyingString, utf8: []const u8) SliceWithUnderlyingString {
        _ = &self;
            return .{ .utf8 = ZigString.Slice.init(bun.default_allocator, utf8), .underlying = String.dead };
    }

pub fn toThreadSafe(self: *SliceWithUnderlyingString) void {
            if ((self.underlying.tag == .WTFStringImpl)) {
                const orig = self.underlying.value.WTFStringImpl;
                _ = self.underlying.toThreadSafe();
                if ((self.underlying.value.WTFStringImpl != orig)) {
                    if (self.utf8.allocator.get()) |allocator| {
                        _ = &allocator;
                        if (String.isWTFAllocator(allocator)) {
                            _ = self.utf8.deinit();
                            self.utf8 = self.underlying.value.WTFStringImpl.toLatin1Slice();
                        }
                    }
                }
            }
    }

pub fn deinit(self: SliceWithUnderlyingString) void {
            _ = self.utf8.deinit();
            _ = self.underlying.deref();
    }

pub fn slice(self: SliceWithUnderlyingString) []const u8 {
            return self.utf8.slice();
    }

pub fn format(self: SliceWithUnderlyingString, writer: *std.Io.Writer) !void {
            if ((self.utf8.len == 0)) {
                _ = try self.underlying.format(writer);
                return;
            }
            _ = try writer.writeAll(self.utf8.slice());
    }
    pub const toJS = string_jsc.sliceWithUnderlyingStringToJS;
    pub const transferToJS = string_jsc.sliceWithUnderlyingStringTransferToJS;
};

